// rfq.js — logique de l'application RFQ (arbre FBS en lecture, fiches SOW par bureau d'etudes
// consulte, export des reponses). Extrait du <script> inline de rfq.html pour la lisibilite.
//
// Depend de (charges avant ce fichier par rfq.html, dans cet ordre) :
//   - SDK Supabase (CDN), auth-gate.js (gate d'acces EkoMa), common.js (makeEl/app/showModal/
//     clone/badges d'acronymes partages avec FBS.html).
// Fournit : les fonctions appelees par les attributs onclick/onchange de rfq.html (refreshFromSupabase,
// openLexiqueViewer, exportSow, resetSow, doSignOut, declareInterest, closeModal...), plus l'etat
// global `state`/`FBS` (donnees FBS en lecture seule + fiches SOW par bureau d'etudes consulte).
//
// A la difference de FBS.html, RFQ ne fait qu'un seul <script> inline a l'origine : pas de section
// "amorçage" separee, la gate d'acces EkoMa est cablee en bas de ce fichier (voir plus bas).

// ===== Helpers & moteur reutilises de la FBS =====
// makeEl() / app() / makeInput() / makeTextarea() / makeSelect() / makeFF() / clone() /
// buildAcrMap() : voir common.js (partage avec FBS.html)

function computeNodes(){
  var acrMap=buildAcrMap(), fbsMap={};
  state.fbs.forEach(function(f){fbsMap[f.id]=f;});
  var seen={}, links=[];
  state.pcrm.forEach(function(l){
    var cid=l.childId, pid=(!l.parentId||l.parentId===cid)?0:l.parentId;
    var k=cid+"|"+pid;
    if(!seen[k]){seen[k]=1;links.push({childId:cid,parentId:pid});}
  });
  if(!links.find(function(l){return l.childId===0;})) links.push({childId:0,parentId:null});
  var res={};
  res["0"]={tvId:"0",tvParent:null,fbsId:0,niveau:0,chemin:"",no:"UrBizia A.P.S.",dc:"",lg:"",idu:"",
    couleur:"#540E28",typeId:"ROOT",typeDes:"",ordre:0,
    phase:"",besoin:"",risque:"",phaseLabel:"",phaseColor:"",besoinLabel:"",besoinColor:"",risqueLabel:"",risqueColor:"",children:[]};
  var changed=true,iter=0;
  while(changed&&iter<30){
    changed=false;iter++;
    links.forEach(function(lnk){
      if(lnk.childId===0) return;
      var pNode=null;
      Object.keys(res).forEach(function(k){if(res[k].fbsId===lnk.parentId)pNode=res[k];});
      if(!pNode) return;
      var exists=false;
      Object.keys(res).forEach(function(k){if(res[k].fbsId===lnk.childId&&res[k].tvParent===pNode.tvId)exists=true;});
      if(exists) return;
      var f=fbsMap[lnk.childId]||{}, tA=acrMap[f.typeId]||{}, pA=acrMap[f.phase]||{}, bA=acrMap[f.besoin]||{}, rA=acrMap[f.risque]||{}, aA=acrMap[f.application]||{};
      var no=f.no||"", chemin=pNode.chemin?pNode.chemin+" > "+no:no;
      var tvId=pNode.tvId+"."+lnk.childId, niveau=pNode.niveau+1;
      var ordre=(tA.ordre||0)*1000000+(pA.ordre||0)*10000+(bA.ordre||0)*100+(rA.ordre||0);
      res[tvId]={tvId:tvId,tvParent:pNode.tvId,fbsId:lnk.childId,niveau:niveau,
        chemin:chemin,no:no,dc:f.dc||"",lg:f.lg||"",idu:f.idu||"",
        couleur:tA.couleur||"#000000",typeId:f.typeId||"",typeDes:tA.designation||"",ordre:ordre,
        phase:f.phase||"",besoin:f.besoin||"",risque:f.risque||"",application:f.application||"",
        phaseLabel:pA.designation||"",phaseColor:pA.couleur||"",
        besoinLabel:bA.designation||"",besoinColor:bA.couleur||"",
        risqueLabel:rA.designation||"",risqueColor:rA.couleur||"",children:[]};
      changed=true;
    });
  }
  Object.keys(res).forEach(function(k){res[k].children=[];});
  Object.keys(res).forEach(function(k){var n=res[k];if(n.tvParent&&res[n.tvParent])res[n.tvParent].children.push(n);});
  Object.keys(res).forEach(function(k){
    res[k].children.sort(function(a,b){
      // 1. EF toujours avant CC
      var aCC=a.typeId==="CC"?1:0, bCC=b.typeId==="CC"?1:0;
      if(aCC!==bCC) return aCC-bCC;
      // 2. Ordre manuel (si defini sur le lien parent-enfant), sinon ordre auto
      var ao=getManualOrder(a.fbsId,a.tvParent), bo=getManualOrder(b.fbsId,b.tvParent);
      if(ao!==null&&bo!==null) return ao-bo;
      if(ao!==null) return -1;
      if(bo!==null) return 1;
      return (a.ordre||0)-(b.ordre||0);
    });
  });
  allNodes=Object.keys(res).map(function(k){return res[k];});
  nodeMap=res;
  treeRoots=allNodes.filter(function(n){return !n.tvParent;});
  updateStats();updateDepthBar();updateFilterDropdowns();
  if(typeof updateOrphanCount==="function")updateOrphanCount();
}

// makeBadgeEl / makePillsEl : voir common.js (partage avec FBS.html)

// Stubs (fonctions FBS non utilisees cote SOW)
function getManualOrder(childFbsId,parentTvId){
  var segs=String(parentTvId).split(".");
  var parentFbsId=parseInt(segs[segs.length-1]); if(isNaN(parentFbsId))parentFbsId=0;
  var lnk=state.pcrm.find(function(l){return l.childId===childFbsId&&l.parentId===parentFbsId;});
  return (lnk&&typeof lnk.ord==="number")?lnk.ord:null;
}
function updateStats(){}
function updateDepthBar(){}
function updateFilterDropdowns(){}
function updateOrphanCount(){}

