// Remplace les logos embarques par la derniere version vectorielle si disponible (identite visuelle
// UrBizia centralisee dans acronymes.icon_svg — voir EkoMa/StatSan/SpotSan). Logo principal : icone
// RFQ si elle a ete fournie, sinon repli sur la marque UrBizia generique. Petit logo secondaire
// ("est un service UrBizia") : toujours la marque UrBizia. Repli silencieux sur LOGO_B64 (deja
// affiche ci-dessus) en cas d'echec reseau ou d'absence des lignes.
(async () => {
  try {
    const resp = await fetch(SUPABASE_URL + '/rest/v1/acronymes?id=in.(RFQ,UrBizia)&select=id,icon_svg', {
      headers: { 'apikey': SUPABASE_ANON_KEY }
    });
    if (!resp.ok) return;
    const rows = await resp.json();
    const byId = {}; (rows || []).forEach(r => { byId[r.id] = r.icon_svg; });
    const mainSvg = byId.RFQ || byId.UrBizia;
    const urbiziaSvg = byId.UrBizia;
    const mainUri = mainSvg && ('data:image/svg+xml;utf8,' + encodeURIComponent(mainSvg));
    const urbiziaUri = urbiziaSvg && ('data:image/svg+xml;utf8,' + encodeURIComponent(urbiziaSvg));
    if (mainUri) ['logo-app-login'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.src = mainUri;
    });
    if (urbiziaUri) ['logo-footer-auth', 'logo-footer-topbar'].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.src = urbiziaUri;
    });
  } catch (e) { /* repli sur LOGO_B64 */ }
})();

