// --- Chargement de la base FBS + BE depuis Supabase (remplace l'ancien import JSON manuel) ---
async function refreshFromSupabase(){
  if(!currentUserId)return;
  try{
    var res=await Promise.all([
      sb.from("fbs").select("*"),
      sb.from("pcrm").select("*"),
      sb.from("acronymes").select("*"),
      sb.from("competences").select("label"),
      sb.from("lexique").select("*"),
      sb.from("lexique_domaines").select("label"),
      sb.from("contractors").select("*")
    ]);
    var fbsR=res[0],pcrmR=res[1],acrR=res[2],compR=res[3],lexR=res[4],lexDomR=res[5],ctrR=res[6];
    [fbsR,pcrmR,acrR,compR,lexR,lexDomR,ctrR].forEach(function(r){if(r.error)throw r.error;});
    var d={
      fbs:(fbsR.data||[]).map(function(r){return {id:r.id, idu:r.idu, typeId:r.type_id, no:r.no, dc:r.dc, lg:r.lg, ref:r.ref, refOrig:r.ref_orig, phase:r.phase, besoin:r.besoin, risque:r.risque, competences:r.competences||[], application:r.application, illustrations:r.illustrations||[]};}),
      pcrm:(pcrmR.data||[]).map(function(r){return {childId:r.child_id, parentId:(r.parent_id===null?0:r.parent_id), ord:r.ord};}),
      acronymes:(acrR.data||[]).map(function(r){return {id:r.id, categorie:r.categorie, ordre:r.ordre, designation:r.designation, couleur:r.couleur, iconBase64:r.icon_base64};}),
      competences:(compR.data||[]).map(function(r){return r.label;}),
      lexique:(lexR.data||[]).map(function(r){return {expression:r.expression, equivalence:r.equivalence, acronyme:r.acronyme, domaines:r.domaines||[], definition:r.definition};}),
      lexiqueDomaines:(lexDomR.data||[]).map(function(r){return r.label;}),
      contractors:(ctrR.data||[]).map(function(r){return {id:r.id, nom:r.nom, contact:r.contact};})
    };
    FBS=d;state=FBS;
    computeNodes();
    if(currentBE){
      currentBE = state.contractors.find(function(c){return c.id===currentBE.id;}) || null;
    }
    if(!currentBE){
      var savedId=null; try{savedId=localStorage.getItem(SK_BE);}catch(e){}
      if(savedId) currentBE = state.contractors.find(function(c){return c.id===savedId;}) || null;
    }
    await loadSow();
    cleanOrphanFiches();
    renderAll();
  }catch(e){
    console.error("refreshFromSupabase failed",e);
    alert("Erreur lors du chargement des donnees depuis Supabase : "+(e.message||e));
  }
}

// --- Fiches SOW du BE courant (table rfq_fiches, propriete de l'utilisateur connecte) ---
async function loadSow(){
  sowFiches={};
  if(!currentBE||!currentUserId)return;
  try{
    var res=await sb.from("rfq_fiches").select("*").eq("owner_id",currentUserId).eq("contractor_id",currentBE.id);
    if(res.error)throw res.error;
    (res.data||[]).forEach(function(r){
      sowFiches[r.fbs_id]={savoir:r.savoir||"",savoirFaire:r.savoir_faire||"",prototype:r.prototype||"",demonstrateur:r.demonstrateur||"",hypotheses:r.hypotheses||"",levees:r.levees||"",exclusions:r.exclusions||"",ressources:r.ressources||"",delais:r.delais||""};
    });
  }catch(e){console.error("loadSow failed",e);}
}
async function persistSow(){
  if(!currentBE||!currentUserId)return;
  try{
    var rows=Object.keys(sowFiches).map(function(fid){
      var fi=sowFiches[fid];
      return {contractor_id:currentBE.id, fbs_id:parseInt(fid), savoir:fi.savoir||"", savoir_faire:fi.savoirFaire||"", prototype:fi.prototype||"", demonstrateur:fi.demonstrateur||"", hypotheses:fi.hypotheses||"", levees:fi.levees||"", exclusions:fi.exclusions||"", ressources:fi.ressources||"", delais:fi.delais||"", owner_id:currentUserId};
    });
    if(rows.length){var up=await sb.from("rfq_fiches").upsert(rows,{onConflict:"contractor_id,fbs_id"});if(up.error)throw up.error;}
    var existing=(await sb.from("rfq_fiches").select("id,fbs_id").eq("owner_id",currentUserId).eq("contractor_id",currentBE.id)).data||[];
    var keepIds={}; Object.keys(sowFiches).forEach(function(fid){keepIds[parseInt(fid)]=true;});
    var toDelete=existing.filter(function(r){return !keepIds[r.fbs_id];}).map(function(r){return r.id;});
    if(toDelete.length){var del=await sb.from("rfq_fiches").delete().in("id",toDelete);if(del.error)throw del.error;}
  }catch(e){
    console.error("persistSow failed",e);
    alert("Erreur de synchronisation Supabase : "+(e.message||e));
  }
}

// --- Identification du BE ---
function renderBESelector(){
  var box=document.getElementById("be-selector");
  box.innerHTML="";
  if(!FBS){box.appendChild(makeEl("span",{style:{color:"var(--text3)",fontSize:"11px"}},"Chargement de la base FBS..."));return;}
  var label=makeEl("span",{style:{fontSize:"11px",color:"var(--text2)"}},"Bureau d'etude : ");
  box.appendChild(label);
  // Liste des consultes declares (table contractors, partagee avec FBS)
  var consultes=(FBS.contractors||[]);
  var sel=makeEl("select",{style:{background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"6px",padding:"4px 8px",color:"var(--text)",fontSize:"11px",outline:"none"}});
  sel.appendChild(makeEl("option",{value:""},"-- Choisir / saisir --"));
  consultes.forEach(function(c){
    var o=makeEl("option",{value:c.id},c.nom);
    if(currentBE&&currentBE.id===c.id)o.selected=true;
    sel.appendChild(o);
  });
  sel.appendChild(makeEl("option",{value:"__autre__"},"Autre (saisir)..."));
  sel.onchange=function(){
    if(this.value==="__autre__"){
      var nom=prompt("Nom du bureau d'etude :","");
      if(nom){var contact=prompt("Contact (email) :","");createContractorAndSelect(nom,contact||"");}
    }else if(this.value){
      var c=consultes.find(function(x){return x.id===this.value;});
      if(c)selectBE(c);
    }
  };
  box.appendChild(sel);
  if(currentBE){
    box.appendChild(makeEl("span",{style:{fontSize:"11px",color:"#86efac",marginLeft:"8px",fontWeight:"bold"}},currentBE.nom+(currentBE.contact?" ("+currentBE.contact+")":"")));
  }
}
function selectBE(c){
  currentBE=c;
  try{localStorage.setItem(SK_BE,c.id);}catch(e){}
  loadSow().then(function(){renderAll();});
}
async function createContractorAndSelect(nom,contact){
  if(!currentUserId)return;
  var id="BE-"+Date.now();
  try{
    var res=await sb.from("contractors").insert({id:id,nom:nom,contact:contact,owner_id:currentUserId}).select().single();
    if(res.error)throw res.error;
    if(!FBS.contractors)FBS.contractors=[];
    FBS.contractors.push(res.data);
    selectBE(res.data);
  }catch(e){alert("Erreur creation bureau d'etudes : "+(e.message||e));}
}

// --- Filtre competence ---
function renderCompetenceFilter(){
  var box=document.getElementById("comp-filter");
  box.innerHTML="";
  if(!FBS)return;
  box.appendChild(makeEl("span",{style:{fontSize:"11px",color:"var(--text2)"}},"Filtre metier : "));
  var sel=makeEl("select",{style:{background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"6px",padding:"4px 8px",color:"var(--text)",fontSize:"11px",outline:"none"}});
  sel.appendChild(makeEl("option",{value:""},"Tous les metiers"));
  (FBS.competences||[]).slice().sort().forEach(function(c){
    var o=makeEl("option",{value:c},c);
    if(filterCompetence===c)o.selected=true;
    sel.appendChild(o);
  });
  sel.onchange=function(){filterCompetence=this.value;renderTree();};
  box.appendChild(sel);
}

// --- L'EF a-t-il (ou un descendant) la competence filtree ? ---
function nodeHasCompetence(node){
  if(!filterCompetence)return true;
  var f=state.fbs.find(function(x){return x.id===node.fbsId;});
  if(f&&f.competences&&f.competences.indexOf(filterCompetence)>=0)return true;
  return false;
}
function subtreeHasCompetence(node){
  if(nodeHasCompetence(node))return true;
  for(var i=0;i<(node.children||[]).length;i++){if(subtreeHasCompetence(node.children[i]))return true;}
  return false;
}

// --- Etat d'une fiche : 'none' | 'created' | 'filled' ---
function ficheState(fbsId){
  var fi=sowFiches[fbsId];
  if(!fi)return "none";
  if(fi.savoir&&fi.savoirFaire&&fi.prototype&&fi.demonstrateur)return "filled";
  return "created";
}

// --- Rendu de l'arbre (lecture seule + clic droit) ---
function renderTree(){
  renderCompetenceFilter();
  var c=document.getElementById("tree-scroll");
  if(!c)return;
  c.innerHTML="";
  if(!FBS){c.appendChild(makeEl("div",{style:{padding:"20px",color:"var(--text3)",fontSize:"12px"}},"Importez la base FBS pour commencer."));return;}
  // Conteneur a largeur automatique pour declencher l'ascenseur horizontal
  var inner=makeEl("div",{style:{display:"inline-block",minWidth:"100%"}});
  treeRoots.forEach(function(r){renderNodeSow(r,inner,0);});
  c.appendChild(inner);
}


function renderNodeSow(node,container,depth){
  // Filtre competence : ne montrer que les branches concernees
  if(filterCompetence && !subtreeHasCompetence(node) && node.typeId!=="ROOT")return;
  var acrMapB=buildAcrMap();
  var isOpen=expandState[node.tvId]!==false;
  var isSel=(selectedNodeId===node.fbsId && selectedTv===node.tvId);
  var indent=Math.min(depth*30,180);
  var wrap=document.createElement("div");
  var row=document.createElement("div");
  var selCls=isSel?(node.typeId==="CC"?"sel-cc":node.typeId==="ROOT"?"sel-root":"sel-ef"):"";
  row.className="node-row "+selCls;
  row.style.paddingLeft=(indent+4)+"px";
  row.onclick=function(){selectSowNode(node);};
  if(node.typeId!=="ROOT" && node.typeId!=="CC"){
    row.oncontextmenu=function(e){e.preventDefault();e.stopPropagation();selectSowNode(node);showSowCtx(e.clientX,e.clientY,node);};
  }

  var hasKids=node.children&&node.children.length;
  var tog=document.createElement("span");
  tog.className="tog";
  tog.textContent=hasKids?(isOpen?"v":">"):" ";
  if(hasKids)tog.onclick=function(e){e.stopPropagation();expandState[node.tvId]=(expandState[node.tvId]===false);renderTree();};
  row.appendChild(tog);

  // Badge du type (EF/CC/Racine), meme logique que la FBS
  var badge=document.createElement("span");
  var typeAcr=acrMapB[node.typeId]||acrMapB["Racine"];
  if(node.typeId==="ROOT"){
    badge.className="badge broot";
    var rootAcr=acrMapB["Racine"];
    if(rootAcr&&rootAcr.iconBase64){
      var ri=document.createElement("img");
      ri.src="data:image/png;base64,"+rootAcr.iconBase64;
      ri.style.width="14px";ri.style.height="14px";ri.style.objectFit="contain";ri.style.verticalAlign="middle";
      badge.appendChild(ri);
    } else { badge.textContent="R"; }
  } else if(typeAcr&&typeAcr.iconBase64){
    badge.className="badge-icon";
    var ti=document.createElement("img");
    ti.src="data:image/png;base64,"+typeAcr.iconBase64;
    ti.style.width="18px";ti.style.height="18px";ti.style.objectFit="contain";ti.style.verticalAlign="middle";
    ti.title=typeAcr.designation||node.typeId;
    badge.appendChild(ti);
  } else {
    badge.className="badge "+(node.typeId==="CC"?"bcc":"bef");
    badge.textContent=node.typeId||"?";
  }
  row.appendChild(badge);

  // Indicateur fiche SOW (rouge cree / vert rempli) - propre a RFQ, pas de badge equivalent en FBS
  if(node.typeId!=="ROOT" && node.typeId!=="CC"){
    var st=ficheState(node.fbsId);
    if(st!=="none"){
      var dot=document.createElement("span");
      dot.style.display="inline-block";dot.style.width="9px";dot.style.height="9px";dot.style.borderRadius="50%";
      dot.style.background=st==="filled"?"#16a34a":"#dc2626";dot.style.flexShrink="0";dot.style.marginRight="1px";
      dot.title=st==="filled"?"Fiche SOW remplie":"Fiche SOW creee (incomplete)";
      row.appendChild(dot);
    }
  }

  if(node.idu){var idu=document.createElement("span");idu.className="nidu";idu.textContent=node.idu;idu.title=node.idu;row.appendChild(idu);}
  var name=document.createElement("span");
  name.className="nname "+(node.typeId==="CC"?"cc-tx":node.typeId==="ROOT"?"root-tx":"ef-tx");
  name.textContent=node.no||node.chemin||node.tvId;
  name.title=node.chemin||node.no||"";
  row.appendChild(name);
  if(node.typeId!=="ROOT")row.appendChild(makePillsEl(node,acrMapB));

  wrap.appendChild(row);

  if(isOpen&&hasKids){
    var ch=document.createElement("div");
    ch.style.borderLeft="1px solid #2d374855";
    ch.style.marginLeft=(indent+18)+"px";
    node.children.forEach(function(k){renderNodeSow(k,ch,depth+1);});
    wrap.appendChild(ch);
  }
  container.appendChild(wrap);
}

// --- Menu contextuel SOW ---
var sowCtxNode=null;
function showSowCtx(x,y,node){
  if(!currentBE){alert("Choisissez d'abord votre bureau d'etude en haut.");return;}
  sowCtxNode=node;
  var menu=document.getElementById("sow-ctx");
  menu.style.display="block";
  menu.style.left=Math.min(x,window.innerWidth-260)+"px";
  menu.style.top=Math.min(y,window.innerHeight-120)+"px";
}
function hideSowCtx(){var m=document.getElementById("sow-ctx");if(m)m.style.display="none";}
document.addEventListener("click",function(){hideSowCtx();});

function declareInterest(scope){
  hideSowCtx();
  if(!sowCtxNode)return;
  var targets=[];
  if(scope==="single"){
    targets=[sowCtxNode.fbsId];
  }else{
    // toutes les fonctions dependantes (EF) selon le filtre en cours
    function collect(n){
      if(n.typeId!=="ROOT"&&n.typeId!=="CC"){
        if(!filterCompetence||subtreeHasCompetence(n)){
          if(!filterCompetence||nodeHasCompetence(n))targets.push(n.fbsId);
        }
      }
      (n.children||[]).forEach(collect);
    }
    collect(sowCtxNode);
  }
  // Creer les fiches (unicite par EF)
  var created=0;
  targets.forEach(function(fid){
    if(!sowFiches[fid]){sowFiches[fid]={savoir:"",savoirFaire:"",prototype:"",demonstrateur:"",hypotheses:"",levees:"",exclusions:"",ressources:"",delais:""};created++;}
  });
  persistSow();renderTree();renderAllInfo();
  if(scope==="single"){selectSowNode(sowCtxNode);}
  else alert(created+" fiche(s) SOW creee(s).");
}

// --- Fiche SOW ---
function tri(label, current, onSet){
  // bouton bascule 3 etats : "" (neutre), val1, val2
  var wrap=makeEl("div",{style:{marginBottom:"10px"}});
  wrap.appendChild(makeEl("div",{style:{fontSize:"11px",color:"var(--text2)",marginBottom:"4px",fontWeight:"bold"}},label.titre));
  var btns=makeEl("div",{style:{display:"flex",gap:"6px"}});
  [["",label.neutre||"Non repondu"],[label.v1key,label.v1],[label.v2key,label.v2]].forEach(function(opt){
    var val=opt[0],txt=opt[1];
    if(val===""){ // bouton neutre non clickable, juste indicateur
      return;
    }
    var active=(current===val);
    var b=makeEl("button",{style:{
      flex:"1",padding:"6px 8px",fontSize:"11px",borderRadius:"6px",cursor:"pointer",
      border:active?"2px solid "+(label.color||"#2563eb"):"1px solid var(--border2)",
      background:active?(label.color||"#2563eb"):"var(--bg3)",
      color:active?"#fff":"var(--text2)",fontWeight:active?"bold":"normal",fontFamily:"inherit"
    }},txt);
    b.onclick=function(){onSet(active?"":val);};
    btns.appendChild(b);
  });
  wrap.appendChild(btns);
  // indicateur etat neutre
  if(!current){
    wrap.appendChild(makeEl("div",{style:{fontSize:"9px",color:"#a16207",marginTop:"2px"}},"(non repondu)"));
  }
  return wrap;
}

function openFiche(fbsId){
  if(!currentBE){alert("Choisissez d'abord votre bureau d'etude.");return;}
  var f=state.fbs.find(function(x){return x.id===fbsId;});
  if(!f)return;
  if(!sowFiches[fbsId])sowFiches[fbsId]={savoir:"",savoirFaire:"",prototype:"",demonstrateur:"",hypotheses:"",levees:"",exclusions:"",ressources:"",delais:""};
  var fi=sowFiches[fbsId];

  var body=makeEl("div");
  body.appendChild(makeEl("div",{style:{fontSize:"14px",fontWeight:"bold",color:"#81093C",marginBottom:"2px"}},(f.idu?f.idu+" - ":"")+f.no));
  if(f.dc)body.appendChild(makeEl("div",{style:{fontSize:"11px",color:"var(--text3)",marginBottom:"10px"}},f.dc));

  function rerender(){openFiche(fbsId);}

  body.appendChild(tri({titre:"Savoir",v1key:"acquis",v1:"Acquis",v2key:"encours",v2:"En cours d'acquisition",color:"#2563eb"},
    fi.savoir,function(v){fi.savoir=v;persistSow();rerender();renderTree();}));
  body.appendChild(tri({titre:"Savoir-Faire",v1key:"teste",v1:"Teste",v2key:"eprouve",v2:"Eprouve (+10 realisations)",color:"#7c3aed"},
    fi.savoirFaire,function(v){fi.savoirFaire=v;persistSow();rerender();renderTree();}));
  body.appendChild(tri({titre:"Prototype requis",v1key:"oui",v1:"Oui",v2key:"non",v2:"Non",color:"#b45309"},
    fi.prototype,function(v){fi.prototype=v;persistSow();rerender();renderTree();}));
  body.appendChild(tri({titre:"Capacite de realisation du demonstrateur",v1key:"oui",v1:"Oui",v2key:"non",v2:"Non",color:"#15803d"},
    fi.demonstrateur,function(v){fi.demonstrateur=v;persistSow();rerender();renderTree();}));

  // Champs texte/numeriques supplementaires (standards SOW)
  body.appendChild(makeFF("Hypotheses ou remarques",makeTextarea("sow-hyp",fi.hypotheses||"")));
  body.appendChild(makeFF("Levees de doute necessaires",makeTextarea("sow-lev",fi.levees||"")));
  body.appendChild(makeFF("Exclusions",makeTextarea("sow-exc",fi.exclusions||"")));
  var rowNum=makeEl("div",{"class":"form-row"});
  rowNum.appendChild(makeFF("Ressources (jours d'ETP)",makeInput("sow-res",fi.ressources||"")));
  rowNum.appendChild(makeFF("Delais indicatif apres signature (mois)",makeInput("sow-del",fi.delais||"")));
  body.appendChild(rowNum);
  // forcer le type numerique sur ressources et delais + sauvegarde a la volee
  setTimeout(function(){
    var binds=[["sow-hyp","hypotheses"],["sow-lev","levees"],["sow-exc","exclusions"],["sow-res","ressources"],["sow-del","delais"]];
    binds.forEach(function(b){
      var el=document.getElementById(b[0]);
      if(el){
        if(b[0]==="sow-res"||b[0]==="sow-del"){el.type="number";el.min="0";el.style.width="100%";}
        el.oninput=function(){fi[b[1]]=this.value;persistSow();};
      }
    });
  },50);

  // etat
  var st=ficheState(fbsId);
  var stLbl=makeEl("div",{style:{fontSize:"10px",marginTop:"8px",color:st==="filled"?"#16a34a":"#dc2626",fontWeight:"bold"}},
    st==="filled"?"Fiche complete":"Fiche incomplete (les 4 rubriques doivent etre repondues)");
  body.appendChild(stLbl);

  // Boutons de sortie
  var b1=makeEl("button",{"class":"btn"},"Limiter a cette fiche");
  b1.onclick=function(){persistSow();closeModal();renderTree();};
  var b2=makeEl("button",{"class":"btn primary"},"Decliner aux fonctions dependantes");
  b2.onclick=function(){declineToDependents(fbsId);};
  var b3=makeEl("button",{"class":"btn danger"},"Supprimer la fiche");
  b3.onclick=function(){if(confirm("Supprimer cette fiche SOW ?")){delete sowFiches[fbsId];persistSow();closeModal();renderTree();}};
  var b4=makeEl("button",{"class":"btn"},"Fermer");
  b4.onclick=function(){persistSow();closeModal();renderTree();};

  showModal("Fiche SOW",body,[b1,b2,b3,b4],true);
}

function declineToDependents(fbsId){
  // copier les reponses de cette fiche a toutes les fonctions dependantes (selon filtre)
  var fi=sowFiches[fbsId];
  if(!fi)return;
  // retrouver le node de cet EF
  var srcNode=null;
  for(var k in nodeMap){if(nodeMap[k].fbsId===fbsId){srcNode=nodeMap[k];break;}}
  if(!srcNode){closeModal();return;}
  var n=0;
  function collect(node){
    if(node.fbsId!==fbsId && node.typeId!=="ROOT" && node.typeId!=="CC"){
      if(!filterCompetence||nodeHasCompetence(node)){
        sowFiches[node.fbsId]={savoir:fi.savoir,savoirFaire:fi.savoirFaire,prototype:fi.prototype,demonstrateur:fi.demonstrateur,hypotheses:fi.hypotheses,levees:fi.levees,exclusions:fi.exclusions,ressources:fi.ressources,delais:fi.delais};
        n++;
      }
    }
    (node.children||[]).forEach(collect);
  }
  collect(srcNode);
  persistSow();renderTree();renderAllInfo();
  alert("Reponse declinee a "+n+" fonction(s) dependante(s).");
}

// --- Export du JSON SOW (leger) ---
function exportSow(){
  if(!currentBE){alert("Choisissez d'abord votre bureau d'etude.");return;}
  var reponses=[];
  Object.keys(sowFiches).forEach(function(fid){
    var fi=sowFiches[fid];
    var f=state.fbs.find(function(x){return x.id===parseInt(fid);});
    reponses.push({
      fbsId:parseInt(fid),
      idu:f?f.idu:"",
      nom:f?f.no:"",
      savoir:fi.savoir,savoirFaire:fi.savoirFaire,
      prototype:fi.prototype,demonstrateur:fi.demonstrateur,
      hypotheses:fi.hypotheses||"",
      levees:fi.levees||"",
      exclusions:fi.exclusions||"",
      ressources:fi.ressources||"",
      delais:fi.delais||""
    });
  });
  var out={
    _app:"UrBizia SOW",_type:"sow_reponses",
    be:currentBE,
    date:new Date().toISOString().slice(0,10),
    reponses:reponses
  };
  var blob=new Blob([JSON.stringify(out,null,2)],{type:"application/json"});
  var url=URL.createObjectURL(blob);
  var a=document.createElement("a");
  var safeName=(currentBE.nom||"BE").replace(/[^a-zA-Z0-9]/g,"_");
  a.href=url;a.download="UrBizia_SOW_"+safeName+"_"+out.date+".json";
  document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
}

function renderAll(){
  renderBESelector();
  renderCompetenceFilter();
  renderLevelBar();
  renderTree();
  renderAllInfo();
}


