var selectedNodeId=null, selectedTv=null;

function selectSowNode(node){
  selectedNodeId=node.fbsId; selectedTv=node.tvId;
  renderTree();
  renderDSS(node);
  renderSOWPane(node);
}

function acrLabel(id){
  var a=(state.acronymes||[]).find(function(x){return x.id===id;});
  return a?a.designation:id;
}

// --- DSS / FDT : fiche descriptive (lecture seule) ---
function renderDSS(node){
  var p=document.getElementById("dss-pane");
  p.innerHTML="";
  if(!node||node.typeId==="ROOT"){
    p.appendChild(makeEl("div",{style:{color:"var(--text3)",fontSize:"12px"}},"Selectionnez une fonction (EF) ou une contrainte (CC) pour voir sa fiche descriptive."));
    return;
  }
  var f=state.fbs.find(function(x){return x.id===node.fbsId;})||{};
  var isCC=node.typeId==="CC";
  // Titre de section
  p.appendChild(makeEl("div",{style:{fontSize:"9px",textTransform:"uppercase",letterSpacing:".08em",color:"var(--text3)",marginBottom:"6px"}},
    "Design Specification Sheet (DSS) / Fiche de Description Technique (FDT)"));
  // En-tete
  var head=makeEl("div",{style:{display:"flex",alignItems:"baseline",gap:"8px",flexWrap:"wrap",marginBottom:"8px"}});
  head.appendChild(makeEl("span",{style:{fontSize:"15px",fontWeight:"bold",color:isCC?"#0d9488":"#1d4ed8"}},(f.idu?f.idu+" - ":"")+(f.no||"")));
  head.appendChild(makeEl("span",{style:{fontSize:"10px",border:"1px solid var(--border2)",borderRadius:"4px",padding:"0 6px",color:"var(--text3)"}},isCC?"Contrainte de Conception":"Ensemble Fonctionnel"));
  p.appendChild(head);
  // Chemin
  if(node.chemin)p.appendChild(makeEl("div",{style:{fontSize:"10px",color:"var(--text3)",fontStyle:"italic",marginBottom:"8px"}},node.chemin));
  // Caracteristiques (badges texte)
  var carac=[];
  if(f.application)carac.push(["Application",acrLabel(f.application)]);
  if(f.phase)carac.push(["Phase",acrLabel(f.phase)]);
  if(f.besoin)carac.push(["Besoin",acrLabel(f.besoin)]);
  if(f.risque)carac.push(["Risque",acrLabel(f.risque)]);
  if(carac.length){
    var cbox=makeEl("div",{style:{display:"flex",flexWrap:"wrap",gap:"6px",marginBottom:"10px"}});
    carac.forEach(function(c){
      var chip=makeEl("span",{style:{fontSize:"10px",background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"4px",padding:"2px 8px"}});
      chip.appendChild(makeEl("span",{style:{color:"var(--text3)"}},c[0]+": "));
      chip.appendChild(makeEl("span",{style:{color:"var(--text)",fontWeight:"bold"}},c[1]));
      cbox.appendChild(chip);
    });
    p.appendChild(cbox);
  }
  function sec(lbl,val,bg,col){
    if(!val)return;
    var s=makeEl("div",{style:{marginBottom:"10px"}});
    s.appendChild(makeEl("div",{style:{fontSize:"9px",textTransform:"uppercase",color:"var(--text3)",marginBottom:"3px"}},lbl));
    s.appendChild(makeEl("div",{style:{fontSize:"12px",color:col||"var(--text)",lineHeight:"1.5",background:bg||"transparent",padding:bg?"8px":"0",borderRadius:"5px",whiteSpace:"pre-wrap"}},val));
    p.appendChild(s);
  }
  sec(isCC?"Objectif":"Nom",f.no);
  sec(isCC?"Contrainte":"Description",f.dc,"var(--bg3)");
  sec("Lignes Guides",f.lg,"#0d2020","#5eead4");
  // Competences
  if(f.competences&&f.competences.length){
    var cs=makeEl("div",{style:{marginBottom:"10px"}});
    cs.appendChild(makeEl("div",{style:{fontSize:"9px",textTransform:"uppercase",color:"var(--text3)",marginBottom:"3px"}},"Competences Metier"));
    var box=makeEl("div",{style:{display:"flex",flexWrap:"wrap",gap:"4px"}});
    f.competences.forEach(function(c){box.appendChild(makeEl("span",{style:{background:"#1e3a5f",color:"#93c5fd",border:"1px solid #2563eb44",borderRadius:"4px",padding:"2px 8px",fontSize:"10px"}},c));});
    cs.appendChild(box);p.appendChild(cs);
  }
  // Illustrations
  if(f.illustrations&&f.illustrations.length){
    var is=makeEl("div",{style:{marginBottom:"10px"}});
    is.appendChild(makeEl("div",{style:{fontSize:"9px",textTransform:"uppercase",color:"var(--text3)",marginBottom:"3px"}},"Illustrations"));
    f.illustrations.forEach(function(il){
      var a=makeEl("a",{href:il.url,target:"_blank",rel:"noopener",style:{display:"block",color:"#60a5fa",fontSize:"11px",textDecoration:"none",marginBottom:"3px"}},il.desc||il.url);
      is.appendChild(a);
    });
    p.appendChild(is);
  }
}

// --- SOW / OPT : fiche de reponse (modifiable, EF uniquement) ---
function renderSOWPane(node){
  var p=document.getElementById("sow-pane");
  p.innerHTML="";
  if(!node||node.typeId==="ROOT"){p.innerHTML="";return;}
  var isCC=node.typeId==="CC";
  p.appendChild(makeEl("div",{style:{fontSize:"9px",textTransform:"uppercase",letterSpacing:".08em",color:"var(--text3)",marginBottom:"6px"}},
    "Statement of Work (SOW) / Offre de Prestation Technique (OPT)"));
  if(isCC){
    p.appendChild(makeEl("div",{style:{color:"var(--text3)",fontSize:"11px"}},"Les contraintes de conception (CC) ne recoivent pas de fiche de reponse. Selectionnez une fonction (EF)."));
    return;
  }
  if(!currentBE){
    p.appendChild(makeEl("div",{style:{color:"#a16207",fontSize:"11px"}},"Choisissez votre bureau d'etude en haut pour pouvoir repondre."));
    return;
  }
  var fbsId=node.fbsId;
  var engaged=ficheState(fbsId)!=="none";
  if(!engaged){
    var info=makeEl("div",{style:{fontSize:"11px",color:"var(--text2)",marginBottom:"10px"}},"Vous n'avez pas encore declare d'interet pour cette fonction.");
    p.appendChild(info);
    var b=makeEl("button",{"class":"btn primary"},"Declarer mon interet et ouvrir une fiche");
    b.onclick=function(){sowFiches[fbsId]={savoir:"",savoirFaire:"",prototype:"",demonstrateur:"",hypotheses:"",levees:"",exclusions:"",ressources:"",delais:""};persistSow();renderTree();renderSOWPane(node);renderAllInfo();};
    p.appendChild(b);
    return;
  }
  var fi=sowFiches[fbsId];

  // Bouton cyclique : neutre (gris) -> v1 (bleu) -> v2 (jaune) -> neutre ...
  // labels = {neutre, v1key, v1lbl, v2key, v2lbl}
  function cycleBtn(labels,cur,onSet){
    var wrap=makeEl("div",{style:{marginBottom:"8px"}});
    var state,bg,fg,txt,bd;
    if(cur===labels.v1key){state=1;bg="#1e3a5f";fg="#bfdbfe";bd="#3b6ea5";txt=labels.v1lbl;}
    else if(cur===labels.v2key){state=2;bg="#10403c";fg="#99f6e4";bd="#2f7d75";txt=labels.v2lbl;}
    else{state=0;bg="var(--bg3)";fg="var(--text3)";bd="var(--border2)";txt=labels.neutre;}
    var b=makeEl("button",{style:{width:"100%",padding:"8px 10px",fontSize:"12px",borderRadius:"6px",cursor:"pointer",border:"1px solid "+bd,background:bg,color:fg,fontWeight:state?"bold":"normal",fontFamily:"inherit",textAlign:"left"}},txt);
    b.onclick=function(){
      // cycle : 0 -> v1 -> v2 -> 0
      var next = state===0?labels.v1key : (state===1?labels.v2key : "");
      onSet(next);
    };
    wrap.appendChild(b);
    return wrap;
  }
  function refresh(){renderSOWPane(node);renderTree();renderAllInfo();}
  // 4 boutons cycliques sur 2 colonnes
  var grid=makeEl("div",{style:{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"8px",marginBottom:"4px"}});
  var col1=makeEl("div",{style:{display:"flex",flexDirection:"column",gap:"8px"}});
  var col2=makeEl("div",{style:{display:"flex",flexDirection:"column",gap:"8px"}});
  col1.appendChild(cycleBtn({neutre:"Maitrise du Savoir a definir",v1key:"acquis",v1lbl:"Savoir acquis",v2key:"encours",v2lbl:"Savoir en cours d'acquisition"},fi.savoir,function(v){fi.savoir=v;persistSow();refresh();}));
  col1.appendChild(cycleBtn({neutre:"Maitrise du Savoir-Faire a definir",v1key:"teste",v1lbl:"Savoir-Faire teste",v2key:"eprouve",v2lbl:"Savoir-Faire eprouve (+10 realisations)"},fi.savoirFaire,function(v){fi.savoirFaire=v;persistSow();refresh();}));
  col2.appendChild(cycleBtn({neutre:"Besoin de prototype a definir",v1key:"oui",v1lbl:"Prototype requis : Oui",v2key:"non",v2lbl:"Prototype requis : Non"},fi.prototype,function(v){fi.prototype=v;persistSow();refresh();}));
  col2.appendChild(cycleBtn({neutre:"Capacite demonstrateur a definir",v1key:"oui",v1lbl:"Capacite de realisation du demonstrateur : Oui",v2key:"non",v2lbl:"Capacite de realisation du demonstrateur : Non"},fi.demonstrateur,function(v){fi.demonstrateur=v;persistSow();refresh();}));
  grid.appendChild(col1);grid.appendChild(col2);
  p.appendChild(grid);

  function ta(lbl,key){
    var wrap=makeEl("div",{style:{marginBottom:"8px"}});
    wrap.appendChild(makeEl("label",{style:{display:"block",fontSize:"10px",color:"var(--text3)",marginBottom:"2px"}},lbl));
    var t=makeEl("textarea",{style:{width:"100%",minHeight:"38px",background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"5px",padding:"5px 8px",color:"var(--text)",fontSize:"11px",fontFamily:"inherit",outline:"none",resize:"vertical"}});
    t.value=fi[key]||"";
    t.oninput=function(){fi[key]=this.value;persistSow();};
    wrap.appendChild(t);return wrap;
  }
  p.appendChild(ta("Hypotheses ou remarques","hypotheses"));
  p.appendChild(ta("Levees de doute necessaires","levees"));
  p.appendChild(ta("Exclusions","exclusions"));
  // Numeriques
  var rowN=makeEl("div",{style:{display:"flex",gap:"8px",marginBottom:"8px"}});
  function num(lbl,key){
    var wrap=makeEl("div",{style:{flex:"1"}});
    wrap.appendChild(makeEl("label",{style:{display:"block",fontSize:"10px",color:"var(--text3)",marginBottom:"2px"}},lbl));
    var t=makeEl("input",{type:"number",min:"0",style:{width:"100%",background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"5px",padding:"5px 8px",color:"var(--text)",fontSize:"11px",outline:"none"}});
    t.value=fi[key]||"";
    t.oninput=function(){fi[key]=this.value;persistSow();};
    wrap.appendChild(t);return wrap;
  }
  rowN.appendChild(num("Ressources (jours d'ETP)","ressources"));
  rowN.appendChild(num("Delais indicatif (mois)","delais"));
  p.appendChild(rowN);

  // Etat
  var st=ficheState(fbsId);
  p.appendChild(makeEl("div",{style:{fontSize:"10px",margin:"6px 0",color:st==="filled"?"#16a34a":"#dc2626",fontWeight:"bold"}},
    st==="filled"?"Fiche complete":"Fiche incomplete (4 rubriques requises)"));

  // Actions
  var act=makeEl("div",{style:{display:"flex",gap:"6px",flexWrap:"wrap",marginTop:"8px"}});
  var bDecl=makeEl("button",{"class":"btn primary",style:{fontSize:"10px"}},"Decliner aux fonctions dependantes");
  bDecl.onclick=function(){declineToDependents(fbsId);renderSOWPane(node);};
  var bDel=makeEl("button",{"class":"btn danger",style:{fontSize:"10px"}},"Supprimer la fiche");
  bDel.onclick=function(){if(confirm("Supprimer cette fiche SOW ?")){delete sowFiches[fbsId];persistSow();renderTree();renderSOWPane(node);renderAllInfo();}};
  act.appendChild(bDecl);act.appendChild(bDel);
  p.appendChild(act);
}

function renderAllInfo(){
  var cnt=Object.keys(sowFiches).length;
  var filled=Object.keys(sowFiches).filter(function(k){return ficheState(parseInt(k))==="filled";}).length;
  var info=document.getElementById("sow-info");
  if(info)info.textContent=FBS?(cnt+" fiche(s), "+filled+" complete(s)"):"";
}

// --- Splitter redimensionnable ---
function initSplitter(){
  var sp=document.getElementById("splitter");
  var left=document.getElementById("left-pane");
  var split=document.getElementById("main-split");
  if(!sp||!left||!split)return;
  var dragging=false;
  sp.addEventListener("mousedown",function(e){dragging=true;e.preventDefault();document.body.style.userSelect="none";});
  document.addEventListener("mousemove",function(e){
    if(!dragging)return;
    var rect=split.getBoundingClientRect();
    var w=e.clientX-rect.left;
    if(w<160)w=160; if(w>rect.width-200)w=rect.width-200;
    left.style.width=w+"px";
  });
  document.addEventListener("mouseup",function(){dragging=false;document.body.style.userSelect="";});
}




// --- Deploiement de l'arbre jusqu'a un niveau (pas un filtre) ---
function deployToLevel(lvl){
  // lvl = niveau max ouvert. Au-dela, les noeuds sont replies.
  // On parcourt tous les noeuds et on fixe expandState selon leur profondeur.
  expandState={};
  function walk(node,depth){
    // depth 0 = racine. On ouvre tant que depth < lvl
    if(node.children&&node.children.length){
      expandState[node.tvId]=(depth<lvl);
    }
    (node.children||[]).forEach(function(c){walk(c,depth+1);});
  }
  treeRoots.forEach(function(r){walk(r,0);});
  renderTree();
}
function deployAll(){
  expandState={}; // tout ouvert par defaut (expandState[tv]!==false => ouvert)
  renderTree();
}
function renderLevelBar(){
  var bar=document.getElementById("level-bar");
  if(!bar)return;
  // garder le label, retirer les boutons
  bar.innerHTML='<span style="font-size:11px;color:var(--text2)">Deployer :</span>';
  if(!FBS)return;
  // profondeur max
  var maxD=1;
  function md(n,d){if(d>maxD)maxD=d;(n.children||[]).forEach(function(c){md(c,d+1);});}
  treeRoots.forEach(function(r){md(r,0);});
  for(var lv=1;lv<=maxD;lv++){
    (function(L){
      var b=makeEl("button",{"class":"btn",style:{fontSize:"10px",padding:"2px 8px"}},String(L));
      b.onclick=function(){deployToLevel(L);};
      bar.appendChild(b);
    })(lv);
  }
  var bAll=makeEl("button",{"class":"btn",style:{fontSize:"10px",padding:"2px 8px"}},"Tout");
  bAll.onclick=function(){deployAll();};
  bar.appendChild(bAll);
}


// --- Lexique en lecture seule ---
function openLexiqueViewer(){
  if(!FBS){alert("Importez d'abord la base FBS (le lexique en fait partie).");return;}
  var lex=FBS.lexique||[];
  var body=makeEl("div");
  if(!lex.length){
    body.appendChild(makeEl("div",{style:{color:"var(--text3)",fontSize:"12px",padding:"10px"}},"Aucun terme dans le lexique de cette base."));
    var cb=makeEl("button",{"class":"btn"},"Fermer");cb.onclick=closeModal;
    showModal("Lexique",body,cb,true);return;
  }
  // Barre recherche + filtre domaine
  var bar=makeEl("div",{style:{display:"flex",gap:"8px",marginBottom:"10px",flexWrap:"wrap"}});
  var search=makeEl("input",{placeholder:"Rechercher...",style:{flex:"1",minWidth:"160px",background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"6px",padding:"5px 10px",color:"var(--text)",fontSize:"12px",outline:"none"}});
  var domSel=makeEl("select",{style:{background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"6px",padding:"5px 8px",color:"var(--text)",fontSize:"11px",outline:"none"}});
  // domaines
  var doms={};(FBS.lexiqueDomaines||[]).forEach(function(d){doms[d]=true;});
  lex.forEach(function(e){(e.domaines||[]).forEach(function(d){doms[d]=true;});});
  domSel.appendChild(makeEl("option",{value:""},"Tous les domaines"));
  Object.keys(doms).sort().forEach(function(d){domSel.appendChild(makeEl("option",{value:d},d));});
  app(bar,search,domSel);
  body.appendChild(bar);
  var listBox=makeEl("div",{style:{maxHeight:"55vh",overflowY:"auto"}});
  body.appendChild(listBox);
  function render(){
    var q=(search.value||"").toLowerCase().trim();
    var fd=domSel.value||"";
    listBox.innerHTML="";
    var arr=lex.slice().sort(function(a,b){return (a.expression||"").localeCompare(b.expression||"");});
    var shown=0;
    arr.forEach(function(e){
      if(fd&&(e.domaines||[]).indexOf(fd)<0)return;
      if(q){var hay=[e.expression,e.equivalence,e.acronyme,e.definition,(e.domaines||[]).join(" ")].join(" ").toLowerCase();if(hay.indexOf(q)<0)return;}
      shown++;
      var card=makeEl("div",{style:{background:"var(--bg3)",border:"1px solid var(--border)",borderRadius:"6px",padding:"8px 10px",marginBottom:"6px"}});
      var h=makeEl("div",{style:{display:"flex",alignItems:"baseline",gap:"8px",flexWrap:"wrap"}});
      h.appendChild(makeEl("span",{style:{fontSize:"13px",fontWeight:"bold",color:"#81093C"}},e.expression||""));
      if(e.equivalence)h.appendChild(makeEl("span",{style:{fontSize:"10px",color:"var(--text3)",fontStyle:"italic"}},"= "+e.equivalence));
      if(e.acronyme&&e.acronyme!==e.expression)h.appendChild(makeEl("span",{style:{fontSize:"9px",fontFamily:"monospace",color:"var(--text3)",border:"1px solid var(--border2)",borderRadius:"3px",padding:"0 4px"}},e.acronyme));
      card.appendChild(h);
      if((e.domaines||[]).length){
        var db=makeEl("div",{style:{display:"flex",flexWrap:"wrap",gap:"3px",margin:"4px 0"}});
        e.domaines.forEach(function(d){db.appendChild(makeEl("span",{style:{background:"#1c2e1c",color:"#86efac",border:"1px solid #16653444",borderRadius:"3px",padding:"0 6px",fontSize:"9px"}},d));});
        card.appendChild(db);
      }
      if(e.definition)card.appendChild(makeEl("div",{style:{fontSize:"11px",color:"var(--text2)",lineHeight:"1.4",marginTop:"3px"}},e.definition));
      listBox.appendChild(card);
    });
    if(!shown)listBox.appendChild(makeEl("div",{style:{padding:"14px",textAlign:"center",color:"var(--text3)",fontSize:"11px"}},"Aucun terme ne correspond."));
  }
  search.oninput=render;domSel.onchange=render;
  render();
  var cb=makeEl("button",{"class":"btn"},"Fermer");cb.onclick=closeModal;
  showModal("Lexique (lecture seule)",body,cb,true);
}

// --- Reset explicite des fiches SOW ---
function resetSow(){
  if(!confirm("Effacer TOUTES vos fiches SOW ? Cette action est irreversible."))return;
  sowFiches={};
  persistSow();
  renderTree();renderAllInfo();
  // vider le panneau SOW si une fiche est affichee
  var sp=document.getElementById("sow-pane");if(sp)sp.innerHTML="";
  alert("Toutes les fiches SOW ont ete effacees.");
}

// --- Nettoyage des fiches orphelines (EF disparu de la base) ---
function cleanOrphanFiches(){
  if(!FBS||!FBS.fbs)return 0;
  var validIds={};
  FBS.fbs.forEach(function(f){validIds[f.id]=true;});
  var removed=0;
  Object.keys(sowFiches).forEach(function(fid){
    if(!validIds[parseInt(fid)]){delete sowFiches[fid];removed++;}
  });
  if(removed>0)persistSow();
  return removed;
}

// ===== Gate d'acces EkoMa (auth-gate.js, partage avec FBS) =====
// Remplace l'ancien bloc dupliqué showAuthOverlay/hideAuthOverlay/onAuthenticated/
// onAuthStateChange/verification de session au chargement. Voir auth-gate.js pour le contrat.
//
// renderAll() ci-dessous : dans l'ancien code, l'arbre (vide) etait deja rendu derriere l'overlay
// avant meme la verification de session (cas "pas de session"). initEkoGate() ne redonne pas la
// main avant d'avoir verifie la session, donc on rend une premiere fois ici pour conserver
// exactement le meme comportement visuel (l'overlay, opaque, masque de toute facon cet etat
// intermediaire tant que l'acces n'est pas confirme).
renderAll();
var gate = initEkoGate({
  sb: sb,
  tool: "rfq",
  deniedMessage: "Ce compte n'a pas acces a RFQ. Contactez l'administrateur.",
  onGranted: async function(user){
    currentUserId = user.id;
    await refreshFromSupabase();
    initSplitter();
  },
  onSignedOut: function(){
    currentUserId = null;
  }
});

